"""Test the unchanged scripted adjoint on identical CUDA operands after two startup orders."""

import hashlib
import json
from pathlib import Path
import subprocess
import sys

from rich.console import Console


def worker(order, output):
    import torch
    from bio_inspired_nanochat.synaptic import _scripted_presyn_edge_release_grad as release_grad

    generator = torch.Generator(device="cpu").manual_seed(237)

    def operands(shape, cap, sampled, strided, device):
        extent = (*shape[:2], shape[2] + 2, shape[3]) if strided else shape

        def floats():
            return torch.rand(extent, generator=generator, device="cpu").to(device)[:, :, :shape[2]]

        drive, incoming, calcium, buffer, primed, clamp, reserve, energy, noise, ema = (
            floats() for _ in range(10)
        )
        valid = floats() > 0.1
        mask = (floats() < sampled) & valid
        return (
            2.0 * drive - 1.0, incoming * 1e-5, valid, calcium, buffer, primed, clamp,
            reserve * 5, energy, mask, noise, ema + 0.1,
            0.97, 0.45, 0.08, 0.02, 0.11, 0.41, 1.2, 0.05, cap, 2.0, 1.0,
        )

    def digest(tensor):
        raw = tensor.detach().contiguous().view(torch.uint8).cpu().numpy()
        return hashlib.sha256(raw.tobytes()).hexdigest()

    torch.cuda.set_device(0)
    specs = {
        "zero_count": ((2, 3, 12, 4), 0, 1.0, False),
        "deterministic": ((2, 3, 9, 4), 8, 0.0, True),
        "half_geometry": ((1, 2, 17, 8), 3, 0.35, True),
        "d1_geometry": ((8, 5, 64, 32), 8, 0.12, False),
    }
    cases = {name: operands(*spec, torch.device("cuda", 0)) for name, spec in specs.items()}
    with torch.no_grad():
        if order == "cpu_first":
            cpu_args = tuple(tensor.cpu() if isinstance(tensor, torch.Tensor) else tensor
                             for tensor in cases["deterministic"])
            release_grad(*cpu_args)
            release_grad(*cpu_args)
        for _ in range(3):
            for args in cases.values():
                release_grad(*args)
        values = {name: {"operands": [digest(arg) if isinstance(arg, torch.Tensor) else arg
                                       for arg in args],
                         "result": digest(release_grad(*args)),
                         "repeated": digest(release_grad(*args))}
                  for name, args in cases.items()}
    with output.open("x") as handle:
        json.dump(values, handle, sort_keys=True)


def main(output):
    output.mkdir()
    matches = {}
    for order in ("cuda_first", "cpu_first"):
        rows = output / f"{order}.json"
        subprocess.run([sys.executable, __file__, "worker", order, str(rows)], check=True)
        matches[order] = json.loads(rows.read_bytes())
    gpu, cpu = matches["cuda_first"], matches["cpu_first"]
    assert all(row["result"] == row["repeated"] for arm in matches.values() for row in arm.values())
    assert all(gpu[name]["operands"] == cpu[name]["operands"] for name in gpu)
    differences = [name for name in gpu if gpu[name]["result"] != cpu[name]["result"]]
    report = {"same_operand_differences": differences, "results": matches}
    with (output / "comparison.json").open("x") as handle:
        json.dump(report, handle, indent=2, sort_keys=True)
        handle.write("\n")
    Console().print_json(data={"different_warmed_gradients": differences, "compared_cases": len(gpu)})


if sys.argv[1] == "worker":
    worker(sys.argv[2], Path(sys.argv[3]))
else:
    main(Path(sys.argv[1]))

