"""Compare the actual backward result with a warmed replay of the very same operands."""

import hashlib
import json
import os
from pathlib import Path
import runpy
import subprocess
import sys

from rich.console import Console


def worker(shape_driver, order, target):
    import torch
    from bio_inspired_nanochat import synaptic

    original = synaptic._scripted_presyn_edge_release_grad
    calls = []

    def observe(*args):
        result = original(*args)
        if args[0].is_cuda:
            calls.append((args, result))
        return result

    synaptic._scripted_presyn_edge_release_grad = observe
    try:
        sys.argv = [shape_driver, "worker", order, str(target.with_suffix(".operator.json"))]
        runpy.run_path(shape_driver, run_name="__main__")
    finally:
        synaptic._scripted_presyn_edge_release_grad = original

    def hash_tensor(tensor):
        data = tensor.detach().reshape(-1).contiguous().view(torch.uint8).cpu().numpy()
        return hashlib.sha256(data.tobytes()).hexdigest()

    sequences = {
        "d1_first": ["d1", "deterministic", "half", "zero_count"],
        "half_first": ["half", "zero_count", "d1", "deterministic"],
        "cpu_first": ["zero_count", "deterministic", "half", "d1"],
    }
    expected = sequences[order] * 2
    prime_recorded = len(calls) == len(expected) + 1
    first = calls[0] if prime_recorded else None
    if prime_recorded:
        assert all(left is right for left, right in zip(first[0], calls[1][0], strict=True))
        calls = calls[1:]
    measurements = []
    with torch.no_grad():
        for index, (case, (args, actual)) in enumerate(zip(expected, calls, strict=True)):
            replay = original(*args)
            assert bool(torch.isfinite(actual).all())
            measurements.append({
                "case": case,
                "repeated": index >= len(expected) // 2,
                "operand_sha256": [hash_tensor(arg) if isinstance(arg, torch.Tensor) else arg for arg in args],
                "actual_sha256": hash_tensor(actual),
                "replay_sha256": hash_tensor(replay),
                "replay_exact": torch.equal(actual, replay),
                "max_abs_delta": float((actual - replay).abs().max().item()),
            })
    with target.open("x") as report:
        json.dump({"measurements": measurements, "first_call_discarded": prime_recorded,
                   "discarded_sha256": hash_tensor(first[1]) if first else None}, report, sort_keys=True)


def main(shape_driver, candidate, incumbent, output):
    output.mkdir()
    arms = {
        "incumbent_d1_first": (incumbent, "d1_first"),
        "candidate_d1_first": (candidate, "d1_first"),
        "candidate_half_first": (candidate, "half_first"),
        "candidate_cpu_first": (candidate, "cpu_first"),
    }
    reports = {}
    operator = {}
    for name, (checkout, order) in arms.items():
        Console().print("Exact-operand replay", name)
        target = output / f"{name}.json"
        env = {**os.environ, "PYTHONPATH": str(checkout)}
        subprocess.run([sys.executable, __file__, "worker", str(shape_driver), order, str(target)],
                       cwd=checkout, env=env, check=True)
        reports[name] = json.loads(target.read_bytes())
        operator[name] = json.loads(target.with_suffix(".operator.json").read_bytes())
    cold_comparison = {
        phase: {
            case: [field for field, value in expected.items()
                   if operator["candidate_d1_first"][phase][case][field] != value]
            for case, expected in cases.items()
        } for phase, cases in operator["incumbent_d1_first"].items()
    }
    summary = {
        "replay_mismatches": {arm: [{"case": row["case"], "repeated": row["repeated"],
                                      "max_abs_delta": row["max_abs_delta"]}
                                     for row in report["measurements"] if not row["replay_exact"]]
                               for arm, report in reports.items()},
        "candidate_vs_cold_incumbent_operator_field_differences": cold_comparison,
    }
    with (output / "comparison.json").open("x") as handle:
        json.dump({"summary": summary, "operands": reports, "operator": operator},
                  handle, indent=2, sort_keys=True, allow_nan=False)
        handle.write("\n")
    Console().print_json(data=summary)
    assert not reports["incumbent_d1_first"]["first_call_discarded"]
    assert all(report["first_call_discarded"] for arm, report in reports.items() if arm.startswith("candidate"))
    assert all(not records for arm, records in summary["replay_mismatches"].items() if arm.startswith("candidate"))


if sys.argv[1] == "worker":
    worker(sys.argv[2], sys.argv[3], Path(sys.argv[4]))
else:
    main(*(Path(argument) for argument in sys.argv[1:]))
